// --- Helper functions ---

// Converts a message's timestamp ("2026-10-08T08:29:55.726+0200") into
// seconds since midnight (here 30595.726).
// Returns -1 if the timestamp can't be read.
double timestamp_to_seconds(const json &msg) {
  string s = msg["timestamp"]["$date"].get<string>();
  int h, m;
  double sec;
  if (s.size() < 19 || sscanf(s.c_str() + 11, "%d:%d:%lf", &h, &m, &sec) != 3) {
    return -1.0;
  }
  return h * 3600.0 + m * 60.0 + sec;
}

// --- Filter ---
// Third-order discrete IIR filter: y_k = sum_{i=0..3} b_i x_{k-i} - sum_{i=1..3} a_i y_{k-i}
// x[0], y[0] are the newest values; x[3], y[3] the oldest.
struct IIR3 {
  array<double, 4> b = {1.0, 0.0, 0.0, 0.0};
  array<double, 4> a = {1.0, 0.0, 0.0, 0.0}; // a[0] placeholder
  array<double, 4> x{};  // Filter input history
  array<double, 4> y{};  // Filter output history

  double step(double input) {
    for (int i = 3; i >= 1; --i) {
      x[i] = x[i-1];
      y[i] = y[i-1];
    }
    x[0] = input;
    double out = 0.0;
    for (int i = 0; i <= 3; ++i) {out += b[i] * x[i];}
    for (int i = 1; i <= 3; ++i) {out -= a[i] * y[i];}
    y[0] = out;
    return out;
  }
};


