  // Implement the actual functionality here
  // Return types (full per-host semantics:
  //  .claude/skills/mads-plugin/reference/return-types.md):
  // return_type::success: processing is valid, go to process
  // return_type::retry: skip processing go to next loop
  // return_type::warning: content of _error is tracked with register_event
  // return_type::error: _error is traced, skip process
  // return_type::critical: execution stops
  return_type load_data(json const &input, string topic = "", vector<unsigned char> const *blob = nullptr) override {
    // Do something with the input data
    cout << "load_data: topic = " << topic << endl; // Debugging print, TODO: Remove
    if (!_params_ok) {return return_type::critical;}
    
    // --- Driver Message ---
    if (topic == "driver") {
      if (!input.contains("encoders")) {
        _error = "Driver message without 'encoders' field";
        return return_type::error;
      }
      if (!input.contains("timestamp")) {
        _error = "Driver message without 'timestamp' field";
        return return_type::error;
      }

      // Loading time and encoder counts. NOTE: Only encoder increments k
      // TODO: Change only encoder counting? Update within same timestamps, etc.
      double t  = timestamp_to_seconds(input);
      if (t < 0) {
        _error = "Could not read driver timestamp";
        return return_type::error;
      }
      int left  = input["encoders"].value("left", _current_enc_n_L);
      int right = input["encoders"].value("right", _current_enc_n_R);

      // First message: nothing to compare with yet, just store counts
      if (_first_driver) {
        _current_time = t;
        _current_enc_n_L = left;
        _current_enc_n_R = right;
        _first_driver = false;
        return return_type::retry; // Skip processing
      }

      // Updating variables
      _prev_time = _current_time;
      _current_time = t;
      _prev_enc_n_L = _current_enc_n_L;
      _prev_enc_n_R = _current_enc_n_R;
      _current_enc_n_L = left;
      _current_enc_n_R = right;

      return return_type::success; // Go to process. NOTE: Only encoder messages start process
    }
    
    // --- Gyro Message ---
    else if (topic == "calibrated_imu") {
      // Updating variables
      _current_w_G = input.value("gyro", _current_w_G);
      _have_gyro = true;
    }

    // --- HTC Message ---
    else if (topic == "htc" ) {
      if (!input.contains("Htracker") || !input["Htracker"].contains("pose")) {
        _error = "HTC message without 'Htracker' or 'pose' field";
        return return_type::error;
      }

      const json &H = input["Htracker"]["pose"]["H"];
      _x_H = H[0][3];
      _y_H = H[1][3];
      double yaw_H = atan2(H[1][0].get<double>(), H[0][0].get<double>());
      _attitude_TEST = input["Htracker"]["pose"]["attitude"][2]; // TEST ONLY. TODO: Remove

      if (_first_htc) {
        _attitude_H = yaw_H;
        _first_htc = false;
      } else {
        double d = yaw_H - _prev_yaw_H;
        d = atan2(sin(d), cos(d));  // wrap the change into [-pi, pi]
        _attitude_H += d;
      }
      _prev_yaw_H = yaw_H;
    }

    return return_type::retry; // Ignore all other topics
  }


  // We calculate the average of the last N values for each key and store it
  // into the output json object
  // Return types:
  // return_type::success: result is published
  // return_type::retry: don't publish, go to next loop
  // return_type::warning: content of _error is added to result befor publishing
  // return_type::error: _error is traced via register_event, don't publish
  // return_type::critical: execution stops
  return_type process(json &out, vector<unsigned char> *blob = nullptr) override {
    // Questions:
    // Euler angle vs. H matrix
    // Can we ignore noise with rotation around x and y axis' when we calculate rotation around z

    // Testing:
    // mu and rho variables
    // validate other variables with known robot movement

    encoder_increments();                 // Step 1
    gyro_increment();                     // Step 2
    maneuver_weights();                   // Step 3
    encoder_gyro_fusion();                // Step 4
    encoder_gyro_attitude_estimate();     // Step 5
    attitude_complementary_filter();      // Step 6

    // load the data as necessary and set the fields of the json out variable
    out.clear();
    out["encoder"]["left_enc"] = _current_enc_n_L;
    out["encoder"]["right_enc"] = _current_enc_n_R;
    out["encoder"]["delta_left_enc"] = _current_enc_n_L - _prev_enc_n_L;
    out["encoder"]["delta_right_enc"] = _current_enc_n_R - _prev_enc_n_R;
    out["encoder"]["delta_distance_L"] = _delta_s_L;
    out["encoder"]["delta_distance_R"] = _delta_s_R;
    out["encoder"]["delta_distance_E"] = _delta_s_E;
    out["encoder"]["delta_attitude_E"] = _delta_attitude_E;

    out["gyro"]["T_c"] = _T_c;
    out["gyro"]["delta_attitude_G"] = _delta_attitude_G;

    out["maneuver"]["u"] = _u;
    out["maneuver"]["q"] = _q;
    out["maneuver"]["xi_R"] = _xi_R;

    out["fusion"]["delta_attitude_EG"] = _delta_attitude_EG;
    out["fusion"]["attitude_EG"] = _attitude_EG;

    out["htc"]["x_H"] = _x_H;
    out["htc"]["y_H"] = _y_H;
    out["htc"]["attitude_H"] = _attitude_H;
    out["htc"]["attitude_EULER_ANGLE_TEST"] = _attitude_TEST; // TODO: Remove

    out["Filter"]["attitude_F"] = _attitude_F;

    // This sets the agent_id field in the output json object, only when it is
    // not empty
    if (!_agent_id.empty()) out["agent_id"] = _agent_id;

    if (!_time_ok) {return return_type::warning;}   // publish, with _error attached
    return return_type::success;
  }

  // Shared-memory zero-copy input/output (protocol P9): scaffold the plugin
  // with `mads plugin --zero-copy` to get the load_data_view() and
  // process_shared() hooks.


  void set_params(const json &params) override {
    // Call the parent class method to set the common parameters 
    // (e.g. agent_id, etc.)
    Filter::set_params(params);

    // provide sensible defaults for the parameters by setting e.g.
    // _params["some_field"] = "default_value";
    // more here...
    _params["gyro_bias"] = 0.0; // TODO: Tune the actual value here or .ini
    _params["s_ref"] = 0.002; // TODO: Tune the actual value here or .ini
    _params["b_hp_attitude"] = {1.0, 0.0, 0.0, 0.0}; // TODO: Replace all filter coefficients!!!
    _params["b_lp_attitude"] = {0.0, 0.0, 0.0, 0.0};
    _params["a_attitude"] = {1.0, 0.0, 0.0, 0.0};

    // then merge the defaults with the actually provided parameters
    // params needs to be cast to json
    _params.merge_patch(params);

    if (!_params.contains("wheel_radius") || !_params.contains("wheel_base")) {
      _error = "wheel radius and wheel_base must be set in mads.ini file";
      _params_ok = false;
      return;
    }

    _wheel_radius = _params["wheel_radius"];
    _wheel_base = _params["wheel_base"];
    _gyro_bias = _params["gyro_bias"];
    _s_ref = _params["s_ref"];
    _HP_attitude.b = _params["b_hp_attitude"];
    _LP_attitude.b = _params["b_lp_attitude"];
    _HP_attitude.a = _params["a_attitude"];
    _LP_attitude.a = _params["a_attitude"];

    // Sanity check for sensitive variables
    if (_wheel_radius <= 0 || _wheel_base <= 0 || _s_ref <= 0) {
      _error = "wheel_radius, wheel_base and s_ref must be > 0";
      _params_ok = false;
      return;
    }

    // Complementarity: HP + LP = 1 means b_hp + b_lp = a, coefficient by coefficient
    for (int i = 0; i < 4; ++i) {
      if (fabs(_HP_attitude.b[i] + _LP_attitude.b[i] - _HP_attitude.a[i]) > 1e-6) {
        _error = "Attitude filter is not complementary: b_hp + b_lp != a";
        _params_ok = false;
        return;
      }
    }

    _params_ok = true;
  }

